    for i in 0..17 {
        let chunk = u64::from_le_bytes(pad[i * 8..(i + 1) * 8].try_into().unwrap());
        state[i] ^= chunk;
    }
    keccak_f1600(&mut state);

    let mut out = [0u8; 32];
    for i in 0..4 {
        out[i * 8..(i + 1) * 8].copy_from_slice(&state[i].to_le_bytes());
    }
    out
}

fn keccak_f1600(state: &mut [u64; 25]) {
    for &rc in RC.iter() {
        // Theta
        let mut c = [0u64; 5];
        for x in 0..5 {
            c[x] = state[x] ^ state[x + 5] ^ state[x + 10] ^ state[x + 15] ^ state[x + 20];
        }
        let mut d = [0u64; 5];
        for x in 0..5 {
            d[x] = c[(x + 4) % 5] ^ c[(x + 1) % 5].rotate_left(1);
        }
        for x in 0..5 {
            for y in 0..5 {
                state[x + y * 5] ^= d[x];
            }
        }

        // Rho and Pi
        let mut B = [0u64; 25];
        for x in 0..5 {
            for y in 0..5 {
                let idx = x + y * 5;
                let r = R[idx];
                let new_x = y;
                let new_y = (2 * x + 3 * y) % 5;
                B[new_x + new_y * 5] = state[idx].rotate_left(r);
            }
        }

        // Chi
        for x in 0..5 {
            for y in 0..5 {
