    0x8000000080008081, 0x8000000000008080, 0x0000000080000001, 0x8000000080008008,
];

const R_CONSTANTS: [u32; 25] = [
     0,  1, 62, 28, 27,
    36, 44,  6, 55, 20,
     3, 10, 43, 25, 39,
    41, 45, 15, 21,  8,
    18,  2, 61, 56, 14,
];

pub fn keccak256(data: &[u8]) -> [u8; 32] {
    let mut state = [0u64; 25];
    let rate = 136;
    let mut in_pos = 0;

    while in_pos + rate <= data.len() {
        for i in 0..17 {
            let chunk = u64::from_le_bytes(data[in_pos + i * 8..in_pos + (i + 1) * 8].try_into().unwrap());
            state[i] ^= chunk;
        }
        keccak_f1600(&mut state);
        in_pos += rate;
    }

    let mut pad = vec![0u8; rate];
    let rem = data.len() - in_pos;
    pad[..rem].copy_from_slice(&data[in_pos..]);
    pad[rem] ^= 0x01;
    pad[rate - 1] ^= 0x80;

    for i in 0..17 {
        let chunk = u64::from_le_bytes(pad[i * 8..(i + 1) * 8].try_into().unwrap());
        state[i] ^= chunk;
    }
    keccak_f1600(&mut state);

    let mut out = [0u8; 32];
    for i in 0..4 {
        out[i * 8..(i + 1) * 8].copy_from_slice(&state[i].to_le_bytes());
    }
    out
}

fn keccak_f1600(state: &mut [u64; 25]) {
    for &rc in RC.iter() {
        // Theta
        let mut c = [0u64; 5];
        for x in 0..5 {
            c[x] = state[x] ^ state[x + 5] ^ state[x + 10] ^ state[x + 15] ^ state[x + 20];
        }
        let mut d = [0u64; 5];
        for x in 0..5 {
            d[x] = c[(x + 4) % 5] ^ c[(x + 1) % 5].rotate_left(1);
        }
        for x in 0..5 {
            for y in 0..5 {
                state[x + y * 5] ^= d[x];
            }
        }

        // Rho and Pi
        let mut b = [0u64; 25];
        for x in 0..5 {
            for y in 0..5 {
                let r = R_CONSTANTS[x + y * 5];
                let new_x = y;
                let new_y = (2 * x + 3 * y) % 5;
                b[new_x + new_y * 5] = state[x + y * 5].rotate_left(r);
            }
        }

        // Chi
        for x in 0..5 {
            for y in 0..5 {
                state[x + y * 5] = b[x + y * 5] ^ ((!b[(x + 1) % 5 + y * 5]) & b[(x + 2) % 5 + y * 5]);
            }
        }

        // Iota
        state[0] ^= rc;
    }
}
