use std::fmt;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ParamType {
    Address,
    Bytes,
    Int(usize),
    Uint(usize),
    Bool,
    String,
    Array(Box<ParamType>),
    FixedArray(Box<ParamType>, usize),
    FixedBytes(usize),
    Tuple(Vec<ParamType>),
}

impl ParamType {
    pub fn is_dynamic(&self) -> bool {
        match self {
            ParamType::Bytes | ParamType::String | ParamType::Array(_) => true,
            ParamType::FixedArray(inner, _) => inner.is_dynamic(),
            ParamType::Tuple(inners) => inners.iter().any(|t| t.is_dynamic()),
            _ => false,
        }
    }

    pub fn parse(s: &str) -> Result<Self, anyhow::Error> {
        let s = s.trim();
        if s.is_empty() {
            return Err(anyhow::anyhow!("Invalid data"));
        }

        if s.ends_with(']') {
            let open_bracket = s.rfind('[').ok_or_else(|| anyhow::anyhow!("Invalid data"))?;
            let inner_str = &s[..open_bracket];
            let len_str = &s[open_bracket + 1..s.len() - 1];
            let inner_type = ParamType::parse(inner_str)?;
            if len_str.is_empty() {
                return Ok(ParamType::Array(Box::new(inner_type)));
            } else {
                let len = len_str.parse::<usize>().map_err(|e| anyhow::anyhow!("Integer parsing error: {}", e))?;
                return Ok(ParamType::FixedArray(Box::new(inner_type), len));
            }
        }

        if s.starts_with('(') && s.ends_with(')') {
            let inner = &s[1..s.len() - 1];
            if inner.trim().is_empty() {
                return Ok(ParamType::Tuple(vec![]));
            }
            let parts = split_top_level(inner, ',', '(', ')')?;
            let mut types = Vec::new();
            for part in parts {
                types.push(ParamType::parse(part)?);
            }
            return Ok(ParamType::Tuple(types));
        }

        match s {
            "address" => Ok(ParamType::Address),
            "bytes" => Ok(ParamType::Bytes),
            "bool" => Ok(ParamType::Bool),
            "string" => Ok(ParamType::String),
            "uint" => Ok(ParamType::Uint(256)),
            "int" => Ok(ParamType::Int(256)),
            _ => {
                if let Some(num) = s.strip_prefix("uint") {
                    let bits = num.parse::<usize>().map_err(|_| anyhow::anyhow!("Invalid data"))?;
                    if bits == 0 || bits > 256 || bits % 8 != 0 {
                        return Err(anyhow::anyhow!("Invalid data"));
                    }
                    Ok(ParamType::Uint(bits))
                } else if let Some(num) = s.strip_prefix("int") {
                    let bits = num.parse::<usize>().map_err(|_| anyhow::anyhow!("Invalid data"))?;
                    if bits == 0 || bits > 256 || bits % 8 != 0 {
                        return Err(anyhow::anyhow!("Invalid data"));
                    }
                    Ok(ParamType::Int(bits))
                } else if let Some(num) = s.strip_prefix("bytes") {
                    let len = num.parse::<usize>().map_err(|_| anyhow::anyhow!("Invalid data"))?;
                    if len == 0 || len > 32 {
                        return Err(anyhow::anyhow!("Invalid data"));
                    }
                    Ok(ParamType::FixedBytes(len))
                } else {
                    Err(anyhow::anyhow!("Invalid data"))
                }
            }
        }
    }
}

impl fmt::Display for ParamType {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParamType::Address => write!(f, "address"),
            ParamType::Bytes => write!(f, "bytes"),
            ParamType::Int(bits) => write!(f, "int{}", bits),
            ParamType::Uint(bits) => write!(f, "uint{}", bits),
            ParamType::Bool => write!(f, "bool"),
            ParamType::String => write!(f, "string"),
            ParamType::Array(inner) => write!(f, "{}[]", inner),
            ParamType::FixedArray(inner, len) => write!(f, "{}[{}]", inner, len),
            ParamType::FixedBytes(len) => write!(f, "bytes{}", len),
            ParamType::Tuple(inners) => {
                let strs: Vec<String> = inners.iter().map(|t| t.to_string()).collect();
                write!(f, "({})", strs.join(","))
            }
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Token {
    Address([u8; 20]),
    Bytes(Vec<u8>),
    Int([u8; 32]),
    Uint([u8; 32]),
    Bool(bool),
    String(String),
    Array(Vec<Token>),
    FixedArray(Vec<Token>),
    FixedBytes(Vec<u8>),
    Tuple(Vec<Token>),
}

impl Token {
    pub fn fmt_top(&self) -> String {
        match self {
            Token::String(s) => s.clone(),
            _ => self.fmt_inside(),
        }
    }

    pub fn fmt_inside(&self) -> String {
        match self {
            Token::Address(a) => hex::encode(a),
            Token::Bytes(b) => hex::encode(b),
            Token::Uint(u) => format_uint(u),
            Token::Int(i) => format_int(i),
            Token::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
            Token::String(s) => format!("\"{}\"", s),
            Token::FixedBytes(b) => hex::encode(b),
            Token::Array(tokens) | Token::FixedArray(tokens) => {
                let strs: Vec<String> = tokens.iter().map(|t| t.fmt_inside()).collect();
                format!("[{}]", strs.join(","))
            }
            Token::Tuple(tokens) => {
                let strs: Vec<String> = tokens.iter().map(|t| t.fmt_inside()).collect();
                format!("({})", strs.join(","))
            }
        }
    }
}

impl fmt::Display for Token {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.fmt_top())
    }
}

fn format_uint(u: &[u8; 32]) -> String {
    let mut start = 0;
    while start < 32 && u[start] == 0 {
        start += 1;
    }
    if start == 32 {
        return "0".to_string();
    }
    let mut res = String::new();
    for &b in &u[start..] {
        if res.is_empty() {
            res.push_str(&format!("{:x}", b));
        } else {
            res.push_str(&format!("{:02x}", b));
        }
    }
    res
}

fn format_int(i: &[u8; 32]) -> String {
    if i[0] >= 0x80 {
        // negative int256 -> full 64 hex characters
        hex::encode(i)
    } else {
        format_uint(i)
    }
}

pub fn split_top_level(s: &str, delimiter: char, open_p: char, close_p: char) -> Result<Vec<&str>, anyhow::Error> {
    let mut parts = Vec::new();
    let mut depth_p = 0i32;
    let mut depth_b = 0i32;
    let mut in_quotes = false;
    let mut start = 0;

    let chars: Vec<(usize, char)> = s.char_indices().collect();
    for (i, c) in &chars {
        if *c == '"' {
            in_quotes = !in_quotes;
        } else if !in_quotes {
            if *c == open_p || *c == '(' {
                depth_p += 1;
            } else if *c == close_p || *c == ')' {
                depth_p -= 1;
            } else if *c == '[' {
                depth_b += 1;
            } else if *c == ']' {
                depth_b -= 1;
            } else if *c == delimiter && depth_p <= 0 && depth_b <= 0 {
                parts.push(&s[start..*i]);
                start = i + c.len_utf8();
            }
        }
    }
    if start <= s.len() {
        parts.push(&s[start..]);
    }
    Ok(parts)
}

// Encoding logic
pub fn encode(tokens: &[Token]) -> Vec<u8> {
    let mut head = Vec::new();
    let mut tail = Vec::new();

    let mut head_size = 0usize;
    for token in tokens {
        head_size += get_head_size(token);
    }

    for token in tokens {
        if is_dynamic_token(token) {
            let offset = head_size + tail.len();
            head.extend_from_slice(&encode_u256(offset));
            encode_dynamic_token(token, &mut tail);
        } else {
            encode_static_token(token, &mut head);
        }
    }

    head.extend(tail);
    head
}

fn is_dynamic_token(token: &Token) -> bool {
    match token {
        Token::Bytes(_) | Token::String(_) | Token::Array(_) => true,
        Token::FixedArray(tokens) => tokens.iter().any(is_dynamic_token),
        Token::Tuple(tokens) => tokens.iter().any(is_dynamic_token),
        _ => false,
    }
}

fn get_head_size(token: &Token) -> usize {
    if is_dynamic_token(token) {
        32
    } else {
        match token {
            Token::FixedArray(tokens) => tokens.iter().map(get_head_size).sum(),
            Token::Tuple(tokens) => tokens.iter().map(get_head_size).sum(),
            _ => 32,
        }
    }
}

fn encode_static_token(token: &Token, out: &mut Vec<u8>) {
    match token {
        Token::Address(a) => {
            out.extend_from_slice(&[0u8; 12]);
            out.extend_from_slice(a);
        }
        Token::Uint(u) | Token::Int(u) => {
            out.extend_from_slice(u);
        }
        Token::Bool(b) => {
            out.extend_from_slice(&[0u8; 31]);
            out.push(if *b { 1 } else { 0 });
        }
        Token::FixedBytes(b) => {
            out.extend_from_slice(b);
            if b.len() < 32 {
                out.extend_from_slice(&vec![0u8; 32 - b.len()]);
            }
        }
        Token::FixedArray(tokens) | Token::Tuple(tokens) => {
            for t in tokens {
                if is_dynamic_token(t) {
                    // Handled elsewhere
                } else {
                    encode_static_token(t, out);
                }
            }
        }
        _ => {}
    }
}

fn encode_dynamic_token(token: &Token, out: &mut Vec<u8>) {
    match token {
        Token::Bytes(b) => {
            out.extend_from_slice(&encode_u256(b.len()));
            out.extend_from_slice(b);
            let pad = (32 - (b.len() % 32)) % 32;
            out.extend_from_slice(&vec![0u8; pad]);
        }
        Token::String(s) => {
            let bytes = s.as_bytes();
            out.extend_from_slice(&encode_u256(bytes.len()));
            out.extend_from_slice(bytes);
            let pad = (32 - (bytes.len() % 32)) % 32;
            out.extend_from_slice(&vec![0u8; pad]);
        }
        Token::Array(tokens) => {
            out.extend_from_slice(&encode_u256(tokens.len()));
            out.extend_from_slice(&encode(tokens));
        }
        Token::FixedArray(tokens) | Token::Tuple(tokens) => {
            out.extend_from_slice(&encode(tokens));
        }
        _ => {}
    }
}

pub fn encode_u256(val: usize) -> [u8; 32] {
    let mut res = [0u8; 32];
    let bytes = (val as u64).to_be_bytes();
    res[24..32].copy_from_slice(&bytes);
    res
}

// Decoding logic
pub fn decode(types: &[ParamType], data: &[u8]) -> Result<Vec<Token>, anyhow::Error> {
    let mut tokens = Vec::new();
    let mut head_offset = 0usize;

    for kind in types {
        if kind.is_dynamic() {
            if head_offset + 32 > data.len() {
                return Err(anyhow::anyhow!("Invalid data"));
            }
            let offset = decode_u256(&data[head_offset..head_offset + 32])?;
            if offset > data.len() {
                return Err(anyhow::anyhow!("Invalid data"));
            }
            let token = decode_dynamic(kind, &data[offset..])?;
            tokens.push(token);
            head_offset += 32;
        } else {
            let (token, size) = decode_static(kind, data, head_offset)?;
            tokens.push(token);
            head_offset += size;
        }
    }

    Ok(tokens)
}

fn decode_u256(slice: &[u8]) -> Result<usize, anyhow::Error> {
    if slice.len() < 32 {
        return Err(anyhow::anyhow!("Invalid data"));
    }
    for &b in &slice[..24] {
        if b != 0 {
            return Err(anyhow::anyhow!("Invalid data"));
        }
    }
    let mut bytes = [0u8; 8];
    bytes.copy_from_slice(&slice[24..32]);
    Ok(u64::from_be_bytes(bytes) as usize)
}

fn decode_static(kind: &ParamType, data: &[u8], offset: usize) -> Result<(Token, usize), anyhow::Error> {
    match kind {
        ParamType::Address => {
            if offset + 32 > data.len() {
                return Err(anyhow::anyhow!("Invalid data"));
            }
            let mut addr = [0u8; 20];
            addr.copy_from_slice(&data[offset + 12..offset + 32]);
            Ok((Token::Address(addr), 32))
        }
        ParamType::Uint(_) => {
            if offset + 32 > data.len() {
                return Err(anyhow::anyhow!("Invalid data"));
            }
            let mut buf = [0u8; 32];
            buf.copy_from_slice(&data[offset..offset + 32]);
            Ok((Token::Uint(buf), 32))
        }
        ParamType::Int(_) => {
            if offset + 32 > data.len() {
                return Err(anyhow::anyhow!("Invalid data"));
            }
            let mut buf = [0u8; 32];
            buf.copy_from_slice(&data[offset..offset + 32]);
            Ok((Token::Int(buf), 32))
        }
        ParamType::Bool => {
            if offset + 32 > data.len() {
                return Err(anyhow::anyhow!("Invalid data"));
            }
            let val = data[offset + 31];
            if val > 1 || data[offset..offset + 31].iter().any(|&b| b != 0) {
                return Err(anyhow::anyhow!("Invalid data"));
            }
            Ok((Token::Bool(val == 1), 32))
        }
        ParamType::FixedBytes(len) => {
            if offset + 32 > data.len() {
                return Err(anyhow::anyhow!("Invalid data"));
            }
            let buf = data[offset..offset + len].to_vec();
            Ok((Token::FixedBytes(buf), 32))
        }
        ParamType::FixedArray(inner, len) => {
            let mut tokens = Vec::new();
            let mut curr_offset = offset;
            for _ in 0..*len {
                let (token, size) = decode_static(inner, data, curr_offset)?;
                tokens.push(token);
                curr_offset += size;
            }
            Ok((Token::FixedArray(tokens), curr_offset - offset))
        }
        ParamType::Tuple(inners) => {
            let mut tokens = Vec::new();
            let mut curr_offset = offset;
            for inner in inners {
                let (token, size) = decode_static(inner, data, curr_offset)?;
                tokens.push(token);
                curr_offset += size;
            }
            Ok((Token::Tuple(tokens), curr_offset - offset))
        }
        _ => Err(anyhow::anyhow!("Invalid data")),
    }
}

fn decode_dynamic(kind: &ParamType, slice: &[u8]) -> Result<Token, anyhow::Error> {
    match kind {
        ParamType::Bytes => {
            if slice.len() < 32 {
                return Err(anyhow::anyhow!("Invalid data"));
            }
            let len = decode_u256(&slice[..32])?;
            if slice.len() < 32 + len {
                return Err(anyhow::anyhow!("Invalid data"));
            }
            Ok(Token::Bytes(slice[32..32 + len].to_vec()))
        }
        ParamType::String => {
            if slice.len() < 32 {
                return Err(anyhow::anyhow!("Invalid data"));
            }
            let len = decode_u256(&slice[..32])?;
            if slice.len() < 32 + len {
                return Err(anyhow::anyhow!("Invalid data"));
            }
            let s = std::str::from_utf8(&slice[32..32 + len]).map_err(|_| anyhow::anyhow!("Invalid data"))?;
            Ok(Token::String(s.to_string()))
        }
        ParamType::Array(inner) => {
            if slice.len() < 32 {
                return Err(anyhow::anyhow!("Invalid data"));
            }
            let len = decode_u256(&slice[..32])?;
            let types = vec![(**inner).clone(); len];
            let tokens = decode(&types, &slice[32..])?;
            Ok(Token::Array(tokens))
        }
        ParamType::FixedArray(inner, len) => {
            let types = vec![(**inner).clone(); *len];
            let tokens = decode(&types, slice)?;
            Ok(Token::FixedArray(tokens))
        }
        ParamType::Tuple(inners) => {
            let tokens = decode(inners, slice)?;
            Ok(Token::Tuple(tokens))
        }
        _ => Err(anyhow::anyhow!("Invalid data")),
    }
}
EOF"}

