fn format_hex_error(err: hex::FromHexError) -> anyhow::Error {
    match err {
        hex::FromHexError::OddLength => anyhow::anyhow!("Hex parsing error: Odd number of digits\n\nCaused by:\n    Odd number of digits"),
        hex::FromHexError::InvalidHexCharacter { c, index } => anyhow::anyhow!("Hex parsing error: Invalid character '{}' at position {}\n\nCaused by:\n    Invalid character '{}' at position {}", c, index, c, index),
        hex::FromHexError::InvalidStringLength => anyhow::anyhow!("Hex parsing error: Invalid string length\n\nCaused by:\n    Invalid string length"),
    }
}

fn parse_dec_u256(s: &str) -> Result<[u8; 32], anyhow::Error> {
    let s = s.trim();
    if s.is_empty() || !s.chars().all(|c| c.is_ascii_digit()) {
        return Err(anyhow::anyhow!("Uint parse error: InvalidCharacter"));
    }
    let mut bytes = [0u8; 32];
    for ch in s.bytes() {
        let digit = (ch - b'0') as u16;
        let mut carry = digit;
        for i in (0..32).rev() {
            let temp = (bytes[i] as u16) * 10 + carry;
            bytes[i] = (temp & 0xff) as u8;
            carry = temp >> 8;
        }
        if carry > 0 {
            return Err(anyhow::anyhow!("Uint parse error: Overflow"));
        }
    }
    Ok(bytes)
}

fn hex_to_u256(s: &str) -> Result<[u8; 32], anyhow::Error> {
    let s = s.trim();
    if s.len() > 64 {
        return Err(anyhow::anyhow!("Uint parse error: Overflow"));
    }
    let padded = format!("{:0>64}", s);
    let bytes = hex::decode(&padded).map_err(|e| format_hex_error(e))?;
    let mut res = [0u8; 32];
    res.copy_from_slice(&bytes);
    Ok(res)
}

fn twos_complement(bytes: &[u8; 32]) -> [u8; 32] {
    let mut res = [0u8; 32];
    let mut carry = 1u16;
    for i in (0..32).rev() {
        let inverted = !bytes[i];
        let sum = (inverted as u16) + carry;
        res[i] = (sum & 0xff) as u8;
        carry = sum >> 8;
    }
    res
}
