    pub components: Option<Vec<Param>>,
}

impl Param {
    pub fn to_param_type(&self) -> Result<ParamType, anyhow::Error> {
        if self.kind_str == "tuple" || self.kind_str.starts_with("tuple[") {
            let suffix = &self.kind_str["tuple".len()..];
            let components = self.components.as_ref().ok_or_else(|| anyhow::anyhow!("Invalid data"))?;
            let mut member_types = Vec::new();
            for c in components {
                member_types.push(c.to_param_type()?);
            }
            let tuple_type = ParamType::Tuple(member_types);
            if suffix.is_empty() {
                Ok(tuple_type)
            } else {
                ParamType::parse(&format!("{}{}", tuple_type, suffix))
            }
        } else {
            ParamType::parse(&self.kind_str)
        }
    }
}

#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct Event {
    pub name: String,
    #[serde(default)]
    pub inputs: Vec<EventParam>,
    #[serde(default)]
    pub anonymous: Option<bool>,
}

impl Event {
    pub fn signature(&self) -> Result<String, anyhow::Error> {
        let mut type_strs = Vec::new();
        for p in &self.inputs {
            let t = p.to_param_type()?;
            type_strs.push(t.to_string());
        }
        Ok(format!("{}({})", self.name, type_strs.join(",")))
    }

    pub fn signature_hash(&self) -> Result<[u8; 32], anyhow::Error> {
        let sig = self.signature()?;
        Ok(keccak256(sig.as_bytes()))
    }
}

#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct EventParam {
    pub name: String,
    #[serde(rename = "type")]
    pub kind_str: String,
    #[serde(default)]
