        }
    }
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum AbiItem {
    #[serde(rename = "function")]
    Function(Function),
    #[serde(rename = "event")]
    Event(Event),
    #[serde(other)]
    Other,
}

#[derive(Debug, Clone)]
pub struct Contract {
    pub functions: Vec<Function>,
    pub events: Vec<Event>,
}

impl Contract {
    pub fn load<P: AsRef<Path>>(path: P) -> Result<Self, anyhow::Error> {
        let content = fs::read_to_string(path)?;
        let items: Vec<AbiItem> = serde_json::from_str(&content).map_err(|e| {
            anyhow::anyhow!("Serialization error: {}\n\nCaused by:\n    {}", e, e)
        })?;

        let mut functions = Vec::new();
        let mut events = Vec::new();

        for item in items {
            match item {
                AbiItem::Function(f) => functions.push(f),
                AbiItem::Event(e) => events.push(e),
                _ => {}
            }
        }

        Ok(Contract { functions, events })
    }

    pub fn function(&self, name_or_sig: &str) -> Result<&Function, anyhow::Error> {
        if name_or_sig.contains('(') {
            // Full signature matching
            let (input_part, output_part) = if let Some(idx) = name_or_sig.find(':') {
                (&name_or_sig[..idx], Some(&name_or_sig[idx + 1..]))
            } else {
                (name_or_sig, None)
            };

            let open_p = input_part.find('(').ok_or_else(|| anyhow::anyhow!("invalid function signature `{}`", name_or_sig))?;
            let close_p = input_part.rfind(')').ok_or_else(|| anyhow::anyhow!("invalid function signature `{}`", name_or_sig))?;
            let name = &input_part[..open_p];
            let in_types_str = &input_part[open_p + 1..close_p];

            let mut req_in_types = Vec::new();
            if !in_types_str.trim().is_empty() {
                let parts = split_top_level(in_types_str, ',', '(', ')')?;
                for p in parts {
                    req_in_types.push(ParamType::parse(p).map_err(|_| anyhow::anyhow!("invalid function signature `{}`", name_or_sig))?);
                }
            }

            let mut req_out_types = Vec::new();
            if let Some(out_str) = output_part {
                let out_inner = if out_str.starts_with('(') && out_str.ends_with(')') {
                    &out_str[1..out_str.len() - 1]
                } else {
                    out_str
                };
                if !out_inner.trim().is_empty() {
                    let parts = split_top_level(out_inner, ',', '(', ')')?;
                    for p in parts {
                        req_out_types.push(ParamType::parse(p).map_err(|_| anyhow::anyhow!("invalid function signature `{}`", name_or_sig))?);
                    }
                }
            }

            for f in &self.functions {
                if f.name == name {
                    let in_t = f.input_types()?;
                    let out_t = f.output_types()?;
                    if in_t == req_in_types && out_t == req_out_types {
                        return Ok(f);
                    }
                }
            }
            Err(anyhow::anyhow!("invalid function signature `{}`", name_or_sig))
        } else {
            // Function name matching
            let matches: Vec<&Function> = self.functions.iter().filter(|f| f.name == name_or_sig).collect();
            if matches.is_empty() {
                Err(anyhow::anyhow!("Invalid name: {}", name_or_sig))
            } else if matches.len() == 1 {
                Ok(matches[0])
            } else {
                Err(anyhow::anyhow!("More than one function found for name `{}`, try providing the full signature", name_or_sig))
            }
        }
    }

    pub fn event(&self, name_or_sig: &str) -> Result<&Event, anyhow::Error> {
        if name_or_sig.contains('(') {
            let open_p = name_or_sig.find('(').ok_or_else(|| anyhow::anyhow!("Invalid name: {}", name_or_sig))?;
            let close_p = name_or_sig.rfind(')').ok_or_else(|| anyhow::anyhow!("Invalid name: {}", name_or_sig))?;
            let name = &name_or_sig[..open_p];
            let in_types_str = &name_or_sig[open_p + 1..close_p];

            let mut req_in_types = Vec::new();
            if !in_types_str.trim().is_empty() {
                let parts = split_top_level(in_types_str, ',', '(', ')')?;
                for p in parts {
                    req_in_types.push(ParamType::parse(p).map_err(|_| anyhow::anyhow!("Invalid name: {}", name_or_sig))?);
                }
            }

            for e in &self.events {
                if e.name == name {
                    let mut in_t = Vec::new();
                    for p in &e.inputs {
                        in_t.push(p.to_param_type()?);
                    }
                    if in_t == req_in_types {
                        return Ok(e);
                    }
                }
            }
            Err(anyhow::anyhow!("Invalid name: {}", name_or_sig))
        } else {
            let matches: Vec<&Event> = self.events.iter().filter(|e| e.name == name_or_sig).collect();
            if matches.is_empty() {
                Err(anyhow::anyhow!("Invalid name: {}", name_or_sig))
            } else {
                Ok(matches[0])
            }
        }
    }
}
EOF"}

