use crate::abi::{ParamType, Token, encode, decode};
use crate::tokenizer::tokenize;

pub fn get_bin_name() -> String {
    let arg0 = env::args().next().unwrap_or_else(|| "ethabi".to_string());
    Path::new(&arg0)
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("ethabi")
        .to_string()
}

pub fn print_help_and_exit(cmd: &[&str]) {
    let bin = get_bin_name();
    let text = match cmd {
        [] => format!(
"ethabi-cli 18.0.0
Ethereum ABI coder

USAGE:
    {} <SUBCOMMAND>

FLAGS:
    -h, --help       Prints help information
    -V, --version    Prints version information

SUBCOMMANDS:
    decode    Decode ABI call result
    encode    Encode ABI call
    help      Prints this message or the help of the given subcommand(s)",
            bin
        ),
        ["encode"] => format!(
"{}-encode 18.0.0
Encode ABI call

USAGE:
    {} encode <SUBCOMMAND>

FLAGS:
    -h, --help       Prints help information
    -V, --version    Prints version information

SUBCOMMANDS:
    function    Load function from JSON ABI file
    help        Prints this message or the help of the given subcommand(s)
    params      Specify types of input params inline",
            bin, bin
        ),
        ["decode"] => format!(
"{}-decode 18.0.0
Decode ABI call result

USAGE:
    {} decode <SUBCOMMAND>

FLAGS:
    -h, --help       Prints help information
    -V, --version    Prints version information

SUBCOMMANDS:
    function    Load function from JSON ABI file
    help        Prints this message or the help of the given subcommand(s)
    log         Decode event log
    params      Specify types of input params inline",
            bin, bin
        ),
        ["encode", "function"] => format!(
"{}-encode-function 18.0.0
Load function from JSON ABI file

USAGE:
    {} encode function [FLAGS] [OPTIONS] <abi-path> <function-name-or-signature>

FLAGS:
    -h, --help       Prints help information
    -l, --lenient    Allow short representation of input params
    -V, --version    Prints version information

OPTIONS:
    -p <params>...        

ARGS:
    <abi-path>                      
    <function-name-or-signature>    ",
            bin, bin
        ),
        ["encode", "params"] => format!(
"{}-encode-params 18.0.0
Specify types of input params inline

USAGE:
    {} encode params [FLAGS] [OPTIONS]

FLAGS:
    -h, --help       
            Prints help information

    -l, --lenient    
            Allow short representation of input params (numbers are in decimal form)

    -V, --version    
            Prints version information


OPTIONS:
    -v <type-or-param> <type-or-param>        
            Pairs of types directly followed by params in the form:

            -v <type1> <param1> -v <type2> <param2> ...",
            bin, bin
        ),
        ["decode", "function"] => format!(
"{}-decode-function 18.0.0
Load function from JSON ABI file

USAGE:
    {} decode function <abi-path> <function-name-or-signature> <data>

FLAGS:
    -h, --help       Prints help information
    -V, --version    Prints version information

ARGS:
    <abi-path>                      
    <function-name-or-signature>    
    <data>                          ",
            bin, bin
        ),
        ["decode", "params"] => format!(
"{}-decode-params 18.0.0
Specify types of input params inline

USAGE:
    {} decode params [OPTIONS] <data>

FLAGS:
    -h, --help       Prints help information
    -V, --version    Prints version information

OPTIONS:
