                            Arg::new("lenient")
                                .short('l')
                                .long("lenient")
                                .action(ArgAction::SetTrue)
                        )
                        .arg(
                            Arg::new("values")
                                .short('v')
                                .num_args(2)
                                .allow_hyphen_values(true)
                                .value_names(["type-or-param", "type-or-param"])
                                .action(ArgAction::Append)
                        )
                )
        )
        .subcommand(
            Command::new("decode")
                .subcommand_required(true)
                .arg_required_else_help(true)
                .disable_help_flag(true)
                .disable_version_flag(true)
                .arg(Arg::new("help").short('h').long("help").action(ArgAction::SetTrue))
                .arg(Arg::new("version").short('V').long("version").action(ArgAction::SetTrue))
                .subcommand(
                    Command::new("function")
                        .disable_help_flag(true)
                        .disable_version_flag(true)
                        .arg(Arg::new("help").short('h').long("help").action(ArgAction::SetTrue))
                        .arg(Arg::new("version").short('V').long("version").action(ArgAction::SetTrue))
                        .arg(
                            Arg::new("abi-path")
                                .required(true)
                                .index(1)
                        )
                        .arg(
                            Arg::new("function-name-or-signature")
                                .required(true)
                                .index(2)
                        )
                        .arg(
                            Arg::new("data")
                                .required(true)
                                .allow_hyphen_values(true)
                                .index(3)
                        )
                )
                .subcommand(
                    Command::new("params")
                        .disable_help_flag(true)
                        .disable_version_flag(true)
                        .arg(Arg::new("help").short('h').long("help").action(ArgAction::SetTrue))
                        .arg(Arg::new("version").short('V').long("version").action(ArgAction::SetTrue))
                        .arg(
                            Arg::new("types")
                                .short('t')
                                .num_args(1)
                                .allow_hyphen_values(true)
                                .action(ArgAction::Append)
                        )
                        .arg(
                            Arg::new("data")
                                .required(true)
                                .allow_hyphen_values(true)
                                .index(1)
                        )
                )
                .subcommand(
                    Command::new("log")
                        .disable_help_flag(true)
                        .disable_version_flag(true)
                        .arg(Arg::new("help").short('h').long("help").action(ArgAction::SetTrue))
                        .arg(Arg::new("version").short('V').long("version").action(ArgAction::SetTrue))
                        .arg(
                            Arg::new("topics")
                                .short('l')
                                .num_args(1)
                                .allow_hyphen_values(true)
                                .action(ArgAction::Append)
                        )
                        .arg(
                            Arg::new("abi-path")
                                .required(true)
                                .index(1)
                        )
                        .arg(
                            Arg::new("event-name-or-signature")
                                .required(true)
                                .index(2)
                        )
                        .arg(
                            Arg::new("data")
                                .required(true)
                                .allow_hyphen_values(true)
                                .index(3)
                        )
                )
        )
}

pub fn run() -> Result<(), anyhow::Error> {
    let args: Vec<String> = env::args().collect();

    let has_help = args.iter().any(|a| a == "-h" || a == "--help");
    let has_version = args.iter().any(|a| a == "-V" || a == "--version");

    if has_version {
        print_version_and_exit();
    }

    if has_help {
        if args.len() >= 3 && args[1] == "encode" && args[2] == "function" {
            print_help_and_exit(&["encode", "function"]);
        } else if args.len() >= 3 && args[1] == "encode" && args[2] == "params" {
            print_help_and_exit(&["encode", "params"]);
        } else if args.len() >= 3 && args[1] == "decode" && args[2] == "function" {
            print_help_and_exit(&["decode", "function"]);
        } else if args.len() >= 3 && args[1] == "decode" && args[2] == "params" {
            print_help_and_exit(&["decode", "params"]);
        } else if args.len() >= 3 && args[1] == "decode" && args[2] == "log" {
            print_help_and_exit(&["decode", "log"]);
        } else if args.len() >= 2 && args[1] == "encode" {
            print_help_and_exit(&["encode"]);
        } else if args.len() >= 2 && args[1] == "decode" {
            print_help_and_exit(&["decode"]);
        } else {
            print_help_and_exit(&[]);
        }
    }

    let matches = match build_cli().try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };

    match matches.subcommand() {
        Some(("encode", encode_matches)) => {
            match encode_matches.subcommand() {
                Some(("function", sub)) => {
                    let lenient = sub.get_flag("lenient");
                    let abi_path = sub.get_one::<String>("abi-path").unwrap();
                    let func_name = sub.get_one::<String>("function-name-or-signature").unwrap();
                    let params: Vec<String> = sub
                        .get_many::<String>("params")
                        .unwrap_or_default()
                        .cloned()
                        .collect();

                    let contract = Contract::load(abi_path)?;
                    let function = contract.function(func_name)?;
                    let input_types = function.input_types()?;

                    if params.len() < input_types.len() {
                        return Err(anyhow::anyhow!("Invalid data"));
                    }

                    let mut tokens = Vec::new();
                    for (i, param_type) in input_types.iter().enumerate() {
                        let tok = tokenize(param_type, &params[i], lenient)?;
                        tokens.push(tok);
                    }

                    let mut result = function.selector()?.to_vec();
                    result.extend(encode(&tokens));
                    println!("{}", hex::encode(result));
                    Ok(())
                }
                Some(("params", sub)) => {
                    let lenient = sub.get_flag("lenient");
                    let values: Vec<String> = sub
                        .get_many::<String>("values")
                        .unwrap_or_default()
                        .cloned()
                        .collect();

                    if values.is_empty() {
                        println!();
                        return Ok(());
                    }

                    let mut tokens = Vec::new();
                    for chunk in values.chunks(2) {
                        if chunk.len() == 2 {
                            let param_type = ParamType::parse(&chunk[0])?;
                            let tok = tokenize(&param_type, &chunk[1], lenient)?;
                            tokens.push(tok);
                        }
                    }

                    let result = encode(&tokens);
                    println!("{}", hex::encode(result));
                    Ok(())
                }
                _ => unreachable!(),
            }
        }
        Some(("decode", decode_matches)) => {
            match decode_matches.subcommand() {
                Some(("function", sub)) => {
                    let abi_path = sub.get_one::<String>("abi-path").unwrap();
                    let func_name = sub.get_one::<String>("function-name-or-signature").unwrap();
                    let data_str = sub.get_one::<String>("data").unwrap();

                    if data_str.is_empty() {
                        return Err(anyhow::anyhow!("Invalid name: please ensure the contract and method you're calling exist! failed to decode empty bytes. if you're using jsonrpc this is likely due to jsonrpc returning `0x` in case contract or method don't exist"));
                    }

                    let bytes = hex::decode(data_str).map_err(format_hex_error)?;
                    let contract = Contract::load(abi_path)?;
                    let function = contract.function(func_name)?;
                    let output_types = function.output_types()?;

                    let tokens = decode(&output_types, &bytes)?;
                    for (i, token) in tokens.iter().enumerate() {
                        println!("{} {}", output_types[i], token);
                    }
                    Ok(())
                }
                Some(("params", sub)) => {
                    let types_strs: Vec<String> = sub
                        .get_many::<String>("types")
                        .unwrap_or_default()
                        .cloned()
                        .collect();
                    let data_str = sub.get_one::<String>("data").unwrap();

                    let bytes = hex::decode(data_str).map_err(format_hex_error)?;
                    let mut types = Vec::new();
                    for t in &types_strs {
                        types.push(ParamType::parse(t)?);
                    }

                    let tokens = decode(&types, &bytes)?;
                    for (i, token) in tokens.iter().enumerate() {
                        println!("{} {}", types[i], token);
                    }
                    Ok(())
                }
                Some(("log", sub)) => {
                    let abi_path = sub.get_one::<String>("abi-path").unwrap();
                    let event_name = sub.get_one::<String>("event-name-or-signature").unwrap();
                    let data_str = sub.get_one::<String>("data").unwrap();
                    let topic_strs: Vec<String> = sub
                        .get_many::<String>("topics")
                        .unwrap_or_default()
                        .cloned()
                        .collect();

                    let contract = Contract::load(abi_path)?;
                    let event = contract.event(event_name)?;

                    let mut topics = Vec::new();
                    for ts in &topic_strs {
                        let v = ts.strip_prefix("0x").or_else(|| ts.strip_prefix("0X")).unwrap_or(ts);
                        if v.len() != 64 {
                            return Err(anyhow::anyhow!("Invalid data"));
                        }
                        let t_bytes = hex::decode(v).map_err(format_hex_error)?;
                        let mut arr = [0u8; 32];
                        arr.copy_from_slice(&t_bytes);
                        topics.push(arr);
                    }

                    let is_anonymous = event.anonymous.unwrap_or(false);
                    let mut topic_idx = 0;
                    if !is_anonymous {
                        let sig_hash = event.signature_hash()?;
                        if topics.is_empty() || topics[0] != sig_hash {
                            return Err(anyhow::anyhow!("Invalid data"));
                        }
                        topic_idx = 1;
                    }

                    let has_non_indexed = event.inputs.iter().any(|p| !p.indexed);
                    if data_str.is_empty() && has_non_indexed {
                        return Err(anyhow::anyhow!("Invalid name: please ensure the contract and method you're calling exist! failed to decode empty bytes. if you're using jsonrpc this is likely due to jsonrpc returning `0x` in case contract or method don't exist"));
                    }

                    let data_bytes = hex::decode(data_str).map_err(format_hex_error)?;

                    let non_indexed_types: Vec<ParamType> = event
                        .inputs
                        .iter()
                        .filter(|p| !p.indexed)
                        .map(|p| p.to_param_type())
                        .collect::<Result<Vec<_>, _>>()?;

                    let non_indexed_tokens = if !non_indexed_types.is_empty() {
                        decode(&non_indexed_types, &data_bytes)?
                    } else {
                        vec![]
                    };

                    let mut non_indexed_iter = non_indexed_tokens.into_iter();

                    for param in &event.inputs {
                        let param_type = param.to_param_type()?;
                        if param.indexed {
                            if topic_idx >= topics.len() {
                                return Err(anyhow::anyhow!("Invalid data"));
                            }
                            let top = topics[topic_idx];
                            topic_idx += 1;
                            let token = if param_type.is_dynamic() {
                                Token::FixedBytes(top.to_vec())
                            } else {
                                let tok = decode(&[param_type], &top)?;
                                tok.into_iter().next().ok_or_else(|| anyhow::anyhow!("Invalid data"))?
                            };
                            println!("{} {}", param.name, token);
                        } else {
                            let token = non_indexed_iter
                                .next()
                                .ok_or_else(|| anyhow::anyhow!("Invalid data"))?;
                            println!("{} {}", param.name, token);
                        }
                    }

                    Ok(())
                }
                _ => unreachable!(),
            }
        }
        _ => unreachable!(),
    }
}

fn format_hex_error(err: hex::FromHexError) -> anyhow::Error {
    match err {
        hex::FromHexError::OddLength => anyhow::anyhow!("Odd number of digits"),
        hex::FromHexError::InvalidHexCharacter { c, index } => anyhow::anyhow!("Invalid character '{}' at position {}", c, index),
        hex::FromHexError::InvalidStringLength => anyhow::anyhow!("Invalid string length"),
    }
}
